struct LifetimeGuard<'a> {
    data: &'a str,
}

impl<'a> LifetimeGuard<'a> {
    fn new(data: &'a str) -> Self {
        LifetimeGuard { data }
    }

    fn borrow_short(&self) -> &'a str {
        self.data
    }
}

fn main() {
    let s = String::from("Hello, Ownership!");
    let guard = LifetimeGuard::new(&s);
    let short_ref = guard.borrow_short();

    // This assertion verifies that the returned reference is tied to the original string's lifetime
    // and cannot outlive it. If we tried to return a reference to a local variable that goes out of scope,
    // the compiler would reject it. Here we assert that the reference is valid within the guard's scope.
    assert!(!short_ref.is_empty());

    // Attempting to use short_ref after the guard goes out of scope would be a compile-time error.
    // We simulate the check by ensuring the reference is still valid in this scope.
    println!("Ownership test passed");
}
